# Generated by build.py from recipe.yml for recipe surl-recover-when-a-port-is-taken. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'start-surl.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Starts surl on the port asked for. If surl exits 45 because the port is taken, starts it`n# again on port 0 and reads the port it chose from its Listening on line. Then fetches`n# hello.txt and stops surl. Any other refusal is passed on. Usage: sh start-surl.sh <port>`nstart() {   # start surl on port `$1; returns 0 once it listens, or surl's exit code`n  surl --directory site `"http://127.0.0.1:`$1/`" > listening.txt 2> surl.log &`n  pid=`$!`n  tries=0`n  until grep -q '^Listening on ' listening.txt; do`n    if ! kill -0 `"`$pid`" 2>/dev/null; then wait `"`$pid`"; return `$?; fi`n    tries=`$((tries + 1))`n    if [ `"`$tries`" -ge 50 ]; then kill `"`$pid`"; return 1; fi`n    sleep 0.1`n  done`n  url=`$(sed -n 's|^Listening on ||p' listening.txt | head -n 1)`n  # The line can come a moment before the port takes connections: wait until it answers.`n  tries=0`n  until curl -s -o /dev/null `"`$url`"; do`n    tries=`$((tries + 1))`n    if [ `"`$tries`" -ge 50 ]; then kill `"`$pid`"; return 1; fi`n    sleep 0.1`n  done`n}`nstart `"`$1`"; code=`$?`nif [ `"`$code`" -eq 45 ]; then`n  echo `"exit 45: `$(cat surl.log)`"`n  start 0; code=`$?`nfi`nif [ `"`$code`" -ne 0 ]; then cat surl.log >&2; exit `"`$code`"; fi`necho `"listening on `$url`"`ncurl -s `"`${url}hello.txt`"`nstatus=`$?`nkill `"`$pid`"`nwait `"`$pid`" 2>/dev/null   # until surl has gone, so it no longer holds site for the next start`nexit `$status`n")
$server0 = Start-Process surl -ArgumentList 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh start-surl.sh 8080 } finally { Stop-Process $server0 }
